use std::{collections::BTreeMap, sync::LazyLock};

use lb_groth16::{CompressedGroth16Proof, Fr};
use lb_key_management_system_keys::keys::{Ed25519Signature, ZkPublicKey};

use crate::{
    mantle::ops::{
        ChannelInscribeProof, ProgramNoteOpening, ProgramProof, ProgramStepProof, StepProof,
        ZkAndEd25519Proof, ZkProgramSpendProof, ZkTransferProof,
    },
    proofs::channel_multi_sig_proof::{ChannelMultiSigProof, IndexedSignatures},
};

pub static ZK_TRANSFER: LazyLock<ZkTransferProof> =
    LazyLock::new(|| ZkTransferProof::new(CompressedGroth16Proof::from_bytes(&[1u8; 128])));

pub static ED25519_SIG: LazyLock<Ed25519Signature> =
    LazyLock::new(|| Ed25519Signature::from_bytes(&[1u8; 64]));

pub static ZK_AND_ED25519_SIGS: LazyLock<ZkAndEd25519Proof> =
    LazyLock::new(|| ZkAndEd25519Proof::new(*ZK_TRANSFER, *ED25519_SIG));

pub static CHANNEL_MULTI_SIG: LazyLock<ChannelMultiSigProof> = LazyLock::new(|| {
    ChannelMultiSigProof::new(IndexedSignatures::new_unchecked(BTreeMap::from([
        (0, Ed25519Signature::from_bytes(&[1u8; 64])),
        (7, Ed25519Signature::from_bytes(&[2u8; 64])),
    ])))
});

pub static CHANNEL_INSCRIBE_PROOF: LazyLock<ChannelInscribeProof> =
    LazyLock::new(|| ChannelInscribeProof::new(*ED25519_SIG, vec![StepProof::User(*ZK_TRANSFER)]));

pub static PROGRAM_STEP_PROOF: LazyLock<ProgramStepProof> = LazyLock::new(|| ProgramStepProof {
    payment_proofs: vec![*ZK_TRANSFER],
    spend_proof: ZkProgramSpendProof::new(CompressedGroth16Proof::from_bytes(&[2u8; 128])),
    program_proof: ProgramProof::new(CompressedGroth16Proof::from_bytes(&[3u8; 128])),
    program_notes: vec![ProgramNoteOpening {
        value: 1,
        nonce: Fr::from(2u64),
        public_key: ZkPublicKey::new(Fr::from(3u64)),
        data: Fr::from(4u64),
    }],
});

pub const ZK_TRANSFER_HEX: &str = "0101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101";
pub const ED25519_SIG_HEX: &str = "01010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101";
pub const ZK_AND_ED25519_SIGS_HEX: &str = "";
pub const CHANNEL_MULTI_SIG_HEX: &str = "0200000001010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101010101070002020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202";
pub const CHANNEL_INSCRIBE_PROOF_HEX: &str = "";
pub const PROGRAM_STEP_PROOF_HEX: &str = "";
